/** Public entry point — the only module consumers/docs should import from. */
export {
  useDataGridPresence,
  useDataGridPresenceHighlights,
  type UseDataGridPresenceOptions,
  type UseDataGridPresenceResult,
} from "./use-data-grid-presence";
export { MAX_RESOLVED_RECTS } from "./presence-overlay";
export { isRowIdPresenceHighlight, isRowIdRangePresenceHighlight } from "./presence-store";
export {
  type PresenceHighlight,
  type RowIdPresenceHighlight,
  type RowIdRangePresenceHighlight,
  type PresenceHighlightEntry,
  type PresenceStoreApi,
} from "./presence-store";

"use client";

import { useEffect, useMemo, useRef, useState, type ComponentType, type ReactNode } from "react";
import { useDataGridRowIdToViewRow, useDataGridVisibleColumns, type DataGridPlugin, type OverlayPluginCtx } from "@/registry/default/components/data-grid/data-grid";
import { isDev, useDataGridStoreApi, viewRowsMoved, visibleColumnsMoved } from "@/registry/default/components/data-grid/data-grid-sdk";
import {
  createPresenceStore,
  isRowIdPresenceHighlight,
  isRowIdRangePresenceHighlight,
  usePresenceHighlights,
  warnDev,
  type PresenceHighlightEntry,
  type PresenceStoreApi,
  type RowIdPresenceHighlight,
  type RowIdRangePresenceHighlight,
} from "./presence-store";
import { renderPresenceOverlay, resolveHighlights } from "./presence-overlay";

/** Options for {@link useDataGridPresence}. */
export type UseDataGridPresenceOptions = {
  /** Cap on the rects one range entry may paint (default {@link MAX_RESOLVED_RECTS}, 1024). Lower it to protect a dense overlay, raise it for a known-large remote selection. */
  maxRects?: number;
  /** Called (dev warning included) when a range entry's fragments exceed the cap — downsample the remote selection or filter it. */
  onExcessRects?: (entry: RowIdRangePresenceHighlight, kept: number, total: number) => void;
};

/** Return value of {@link useDataGridPresence}. */
export type UseDataGridPresenceResult = {
  /** One entry of the grid's `plugins` prop — the plugin's `Overlay` paints the highlights, its `Mount` dev-warns once when rows/columns move under an active view-index entry. Stable for the component's lifetime. An inline `plugins={[plugin]}` is fine: re-resolution is gated on entry identity (name + member references), not on the array's. */
  plugin: DataGridPlugin<unknown>;
  /** The real (imperative) mechanism: call directly from your websocket/CRDT handler. */
  setPresenceHighlights(highlights: readonly PresenceHighlightEntry[]): void;
  /** Removes one entry by `id` (a peer's range closed) — prefer this over resending the whole snapshot. */
  removePresenceHighlight(id: string): void;
  /** Removes every entry (a peer disconnected or the session ended). */
  clearPresenceHighlights(): void;
  /** Opaque handle for {@link useDataGridPresenceHighlights} — pass it through if some other component needs the read-back subscription (e.g. an inspector panel); most consumers never need this. */
  storeApi: PresenceStoreApi;
};

/**
 * Multiplayer presence, as a single hook. Owns its own store — a plain Zustand vanilla store local
 * to this hook instance, NOT part of the grid's own store, so core stays entirely unaware of
 * presence past the generic `plugins` seam.
 *
 * Zero-cell-render contract preserved: `plugin`'s identity never changes across renders (returned
 * from a one-time `useState` initializer), and the plugin's `Overlay` component's own
 * `usePresenceHighlights` subscription only re-renders `DataGridOverlays` (the component that
 * renders the `Overlay` inside its own tree) — never rows or cells.
 *
 * A hook (not a `<DataGridPresence>` component) is the simplest wiring here: the plugin must be
 * threaded into `plugins` on `DataGridProvider`, which sits ABOVE anywhere a child component
 * could register it — a hook called once in the consumer's own component (before rendering the
 * provider) avoids that inversion entirely, with no new context needed.
 */
export function useDataGridPresence(options: UseDataGridPresenceOptions = {}): UseDataGridPresenceResult {
  const [store] = useState(() => createPresenceStore());

  // the plugin closures are memoized once; option callbacks read through refs so a new callback
  // identity (a re-rendering consumer) never re-creates the plugin
  const maxRectsRef = useRef(options.maxRects);
  maxRectsRef.current = options.maxRects;
  const onExcessRectsRef = useRef(options.onExcessRects);
  onExcessRectsRef.current = options.onExcessRects;

  const plugin = useMemo<DataGridPlugin<unknown>>(
    () => ({
      name: "presence",
      Overlay: createPresenceOverlay(store, maxRectsRef, onExcessRectsRef),
      Mount: createPresenceMount(store),
    }),
    [store],
  );

  return {
    plugin,
    setPresenceHighlights: store.getState().setPresenceHighlights,
    removePresenceHighlight: store.getState().removePresenceHighlight,
    clearPresenceHighlights: store.getState().clearPresenceHighlights,
    storeApi: store,
  };
}

/** The plugin's overlay component, closed over the add-on's local store; its hooks subscribe only `DataGridOverlays` (the component rendering it). */
function createPresenceOverlay(
  store: PresenceStoreApi,
  maxRectsRef: { current: number | undefined },
  onExcessRectsRef: { current: ((entry: RowIdRangePresenceHighlight, kept: number, total: number) => void) | undefined },
): ComponentType<OverlayPluginCtx> {
  // per-instance (per plugin closure) once-warns: the overlay re-runs on every DataGridOverlays
  // render, so a persistently hidden/unknown column must not re-warn on every render
  const warnedColumns = new Set<string>();
  const warnedRangeIssues = new Set<string>();
  const warnDroppedColumn = (entry: RowIdPresenceHighlight): void => {
    const key = `${entry.id}:${entry.columnId}`;
    if (warnedColumns.has(key)) return;
    warnedColumns.add(key);
    warnDev(`presence entry "${entry.id}" references column "${entry.columnId}" which is not in the visible columns (hidden or unknown); the entry is dropped`);
  };
  const warnUnresolvedColumns = (entry: RowIdRangePresenceHighlight, unresolvedCount: number): void => {
    const key = `unresolved:${entry.id}`;
    if (warnedRangeIssues.has(key)) return;
    warnedRangeIssues.add(key);
    warnDev(`presence entry "${entry.id}" has ${unresolvedCount} columnId(s) not in the visible columns (hidden or unknown); those cells are dropped`);
  };
  const warnExcessRects = (entry: RowIdRangePresenceHighlight, kept: number, total: number): void => {
    onExcessRectsRef.current?.(entry, kept, total);
    const key = `excess:${entry.id}`;
    if (warnedRangeIssues.has(key)) return;
    warnedRangeIssues.add(key);
    warnDev(`presence entry "${entry.id}" resolves to ${total} fragments, above the ${kept}-rect budget; the excess is not painted (downsample the remote selection or filter it)`);
  };

  function PresenceOverlay(ctx: OverlayPluginCtx): ReactNode {
    const highlights = usePresenceHighlights(store);
    const rowIdToViewRow = useDataGridRowIdToViewRow();
    const visibleColumns = useDataGridVisibleColumns();
    // memoized on the inputs' identity: local selection/keystroke re-renders of DataGridOverlays
    // must not re-run the resolve math or re-allocate the rect objects the memoized overlay nodes
    // compare. maxRects is read through the ref but placed in the deps so a live change re-resolves
    // on the next overlay render.
    const maxRects = maxRectsRef.current;
    const resolved = useMemo(
      () => resolveHighlights(highlights, rowIdToViewRow, visibleColumns, warnDroppedColumn, warnUnresolvedColumns, warnExcessRects, maxRects),
      [highlights, rowIdToViewRow, visibleColumns, warnDroppedColumn, warnUnresolvedColumns, warnExcessRects, maxRects],
    );
    return renderPresenceOverlay(resolved, ctx);
  }
  return PresenceOverlay;
}

/** The plugin's mount component: dev-warns once when a row-moving or column-moving store write lands while a view-index entry is active — that entry's highlight position is now stale (view-index entries follow their rect, not their rows). */
function createPresenceMount(store: PresenceStoreApi): ComponentType {
  function PresenceMount(): ReactNode {
    const gridStoreApi = useDataGridStoreApi();
    useEffect(() => {
      if (!isDev()) return;
      let warned = false;
      const viewSpaceActive = () =>
        store.getState().highlights.some((entry) => !isRowIdPresenceHighlight(entry) && !isRowIdRangePresenceHighlight(entry));
      const unsubscribe = gridStoreApi.subscribe((s, prev) => {
        if (warned || !viewSpaceActive()) return;
        if (viewRowsMoved(prev, s.viewIndex, s.data, s.getRowId) || visibleColumnsMoved(prev.visibleColumns, s.visibleColumns)) {
          warned = true;
          warnDev("rows or columns moved while a view-space presence entry is active — its highlight position is now stale; use rowId-native presence entries for a live feed");
        }
      });
      return unsubscribe;
    }, [gridStoreApi, store]);
    return null;
  }
  return PresenceMount;
}

/** Read-back subscription (opt-in): re-renders ONLY the calling component on highlight changes — pass `storeApi` from {@link useDataGridPresence}'s return value. Mirrors core's old `useDataGridHighlights` for consumers building their own UI (e.g. an inspector panel) off the same state the grid paints. */
export function useDataGridPresenceHighlights(storeApi: PresenceStoreApi): readonly PresenceHighlightEntry[] {
  return usePresenceHighlights(storeApi);
}

"use client";

import { createStore, type StoreApi } from "zustand/vanilla";
import { useStore } from "zustand";
import type { GridRect } from "@/registry/default/components/data-grid/data-grid";
import { isDev } from "@/registry/default/components/data-grid/data-grid-sdk";

/**
 * One remote user's (or cursor's) selection painted into the grid (multiplayer presence),
 * VIEW-space (same coordinate system as `GridSelection.current.range`): indices into the current
 * sorted/filtered display order, not the raw `data` array. A rowId-keyed remote peer must map
 * rowId -> view index itself before building this — either with {@link RowIdPresenceHighlight}
 * (the plugin resolves it for you) or by hand via `useDataGridRowIdToViewRow()`.
 */
export type PresenceHighlight = {
  /**
   * Unique id PER ENTRY — the `id` must be unique per entry: a user with a multi-range selection
   * sends one entry per range, each with its own id. Entries are keyed by position, not id, so
   * duplicate ids no longer break rendering — but they do break any per-user bookkeeping (e.g.
   * clear-on-leave filtering).
   */
  id: string;
  /** Any CSS color, including `var(--color-primary)`; painted at fixed alpha for the fill, full opacity for the border/chip. An invalid color or an undefined token paints as `var(--color-primary)`. The chip text is black on light colors and white on dark ones. */
  color: string;
  range: GridRect;
  /** Optional name chip anchored at the range's top-left corner, only rendered while that corner is on-window. */
  label?: string;
};

/**
 * rowId-native alternative to {@link PresenceHighlight}: a single cell keyed by stable rowId + columnId instead of a view-index rect.
 * The plugin resolves `rowId` -> view row itself at paint time via `useDataGridRowIdToViewRow()`, so
 * a locally-active sort/filter never mispaints it; an entry whose `rowId` fell out of the current
 * view (filtered out) is dropped silently, same contract as the manual mapping it replaces.
 */
export type RowIdPresenceHighlight = {
  /** Unique id PER ENTRY — must be unique per entry (a multi-range selection sends one entry per cell/range, each with its own id). */
  id: string;
  /** Any CSS color, including `var(--color-primary)`; painted at fixed alpha for the fill, full opacity for the border/chip. An invalid color or an undefined token paints as `var(--color-primary)`. The chip text is black on light colors and white on dark ones. */
  color: string;
  rowId: string;
  columnId: string;
  /** Optional name chip anchored at the resolved cell, only rendered while it's on-window. */
  label?: string;
};

/**
 * rowId-native alternative to {@link PresenceHighlight}: a multi-cell selection keyed by stable
 * rowIds × columnIds instead of a view-index rect. The plugin resolves every id against the
 * receiver's current view at paint time, so a local sort or filter never mispaints it. Ids that
 * fell out of the view are dropped; the surviving cells paint one rect per contiguous run.
 */
export type RowIdRangePresenceHighlight = {
  /** Unique id PER ENTRY — must be unique per entry (a multi-range selection sends one entry per range, each with its own id). */
  id: string;
  /** Any CSS color, including `var(--color-primary)`; painted at fixed alpha for the fill, full opacity for the border/chip. An invalid color or an undefined token paints as `var(--color-primary)`. The chip text is black on light colors and white on dark ones. */
  color: string;
  /** Stable row ids of the selected rows; any order, duplicates allowed. */
  rowIds: string[];
  /** Stable column ids of the selected columns; any order, duplicates allowed. */
  columnIds: string[];
  /** Optional name chip anchored at each resolved fragment's top-left corner, only rendered while that corner is on-window. */
  label?: string;
};

/** Any coordinate form a highlight entry can take — {@link PresenceHighlight} (view-index rect), {@link RowIdPresenceHighlight} (rowId-native single cell), or {@link RowIdRangePresenceHighlight} (rowId-native range), distinguished by `rowId` / `rowIds`. When an entry carries BOTH `rowId` and `rowIds`, the single-cell form wins. */
export type PresenceHighlightEntry = PresenceHighlight | RowIdPresenceHighlight | RowIdRangePresenceHighlight;

/**
 * True when `entry` is the rowId-native form — the discriminant used by the plugin to route to the
 * right resolution path. `rowId` must be a non-empty STRING: a missing/null `rowId` (foreign JSON
 * that lost it) is NOT the rowId-native form and falls through to the view-index `range` check
 * instead of being silently misrouted to the rowId path.
 */
export function isRowIdPresenceHighlight(entry: PresenceHighlightEntry): entry is RowIdPresenceHighlight {
  const rowId = (entry as Partial<RowIdPresenceHighlight>).rowId;
  return typeof rowId === "string" && rowId.length > 0;
}

/**
 * True when `entry` is the rowId-native RANGE form — the discriminant that routes it away from the
 * single-cell and view-index paths. `rowIds` must be an ARRAY of strings: a missing/foreign
 * `rowIds` is NOT the range form and falls through to the `rowId`/`range` checks instead of being
 * misrouted.
 */
export function isRowIdRangePresenceHighlight(entry: PresenceHighlightEntry): entry is RowIdRangePresenceHighlight {
  const rowIds = (entry as Partial<RowIdRangePresenceHighlight>).rowIds;
  return Array.isArray(rowIds) && rowIds.every((id) => typeof id === "string");
}

/** A well-formed view-index `range`: all four coordinates finite (catches missing, null, and NaN). */
function isValidRange(range: unknown): range is GridRect {
  if (typeof range !== "object" || range === null) return false;
  const r = range as Partial<GridRect>;
  return Number.isFinite(r.x) && Number.isFinite(r.y) && Number.isFinite(r.width) && Number.isFinite(r.height);
}

/** Dev-only warning, core's `warnDev` pattern with this add-on's own prefix (import-boundary rule: add-ons import only from core's block-root barrel). */
export function warnDev(message: string): void {
  if (isDev()) console.warn(`[data-grid-presence] ${message}`);
}

/** Shared empty-array identity for the no-highlights state, so a grid with none never allocates a fresh `[]` per render. */
const EMPTY_HIGHLIGHTS: readonly PresenceHighlightEntry[] = [];

/** This add-on's own state slice: just the highlight list. Deliberately NOT part of the core store — core knows nothing about presence past the generic `overlayPlugins` seam it renders through. */
export type PresenceStoreState = {
  highlights: readonly PresenceHighlightEntry[];
  setPresenceHighlights(highlights: readonly PresenceHighlightEntry[]): void;
  /** Removes the entry with this `id`; no-op (and the same list identity) when no entry matches. */
  removePresenceHighlight(id: string): void;
  /** Removes every entry — a peer disconnect or session end. */
  clearPresenceHighlights(): void;
};

export type PresenceStoreApi = StoreApi<PresenceStoreState>;

/**
 * One store instance per `useDataGridPresence()` call, mirroring core's one-store-per-grid pattern
 * (store.tsx's `createDataGridStore`). `setPresenceHighlights` REPLACES the whole list (snapshot
 * semantics) and validates/coerces foreign entries on the way in: malformed entries (non-object,
 * missing/malformed `range`) and rowId-native entries without a usable `columnId` (single cell) or
 * `columnIds` string array (range) are DROPPED with a per-instance dev warning instead of painting
 * garbage or failing silently (same for range entries with empty `rowIds`/`columnIds` arrays).
 * View-dependent drops (rowId filtered out of view, hidden/unknown column) happen at resolve
 * time in the plugin.
 */
export function createPresenceStore(): PresenceStoreApi {
  const warned = new Set<string>();
  const warnOnce = (key: string, message: string): void => {
    if (warned.has(key)) return;
    warned.add(key);
    warnDev(message);
  };
  return createStore<PresenceStoreState>((set) => ({
    highlights: EMPTY_HIGHLIGHTS,
    setPresenceHighlights(highlights) {
      const cleaned: PresenceHighlightEntry[] = [];
      for (const entry of highlights) {
        if (!entry || typeof entry !== "object") {
          warnOnce(`entry:${String(entry)}`, "setPresenceHighlights: dropped a non-object entry (the payload should contain PresenceHighlightEntry objects)");
          continue;
        }
        if (isRowIdPresenceHighlight(entry)) {
          if (typeof entry.columnId !== "string" || entry.columnId.length === 0) {
            warnOnce(`columnId:${JSON.stringify(entry)}`, `setPresenceHighlights: dropped rowId-native entry "${entry.id}" — rowId-native entries need a non-empty columnId`);
            continue;
          }
          cleaned.push(entry);
          continue;
        }
        if (isRowIdRangePresenceHighlight(entry)) {
          if (!Array.isArray(entry.columnIds) || !entry.columnIds.every((id) => typeof id === "string")) {
            warnOnce(`rowRange:${JSON.stringify(entry)}`, `setPresenceHighlights: dropped rowId-native range entry "${entry.id}" — rowId-native range entries need a string array columnIds`);
            continue;
          }
          if (entry.rowIds.length === 0 || entry.columnIds.length === 0) {
            warnOnce(`emptyRowRange:${entry.id}`, `setPresenceHighlights: dropped rowId-native range entry "${entry.id}" — empty rowIds/columnIds paint nothing`);
            continue;
          }
          cleaned.push(entry);
          continue;
        }
        if (!isValidRange(entry.range)) {
          warnOnce(`range:${JSON.stringify(entry)}`, `setPresenceHighlights: dropped entry "${entry.id}" — missing or malformed range (need finite x, y, width, height)`);
          continue;
        }
        cleaned.push(entry);
      }
      set({ highlights: cleaned });
    },
    removePresenceHighlight(id) {
      set((s) => (s.highlights.some((h) => h.id === id) ? { highlights: s.highlights.filter((h) => h.id !== id) } : s));
    },
    clearPresenceHighlights() {
      set({ highlights: EMPTY_HIGHLIGHTS });
    },
  }));
}

/** Every active multiplayer presence highlight; consumed ONLY by the overlay plugin — never by row/cell subscriptions, preserving the zero-cell-render contract. */
export function usePresenceHighlights(store: PresenceStoreApi): readonly PresenceHighlightEntry[] {
  return useStore(store, (s) => s.highlights);
}

"use client";

import { Fragment, memo, type CSSProperties, type ReactNode } from "react";
import type { GridRect, OverlayPluginCtx } from "@/registry/default/components/data-grid/data-grid";
import { GRID_LAYER, hasAnyPin } from "@/registry/default/components/data-grid/data-grid-sdk";
import {
  isRowIdPresenceHighlight,
  isRowIdRangePresenceHighlight,
  type PresenceHighlight,
  type PresenceHighlightEntry,
  type RowIdPresenceHighlight,
  type RowIdRangePresenceHighlight,
} from "./presence-store";

/** Default cap on the rects ONE range entry may paint (per contiguous fragment): a remote selection of scattered rows must not turn the overlay layer into thousands of divs. Override it with `useDataGridPresence({ maxRects })`; excess fragments are dropped and reported via the `onExcessRects` option. */
export const MAX_RESOLVED_RECTS = 1024;

const FALLBACK_PRESENCE_COLOR = "var(--color-primary)";

/** Returns `color` when the browser parses it as a CSS color, else `var(--color-primary)`; passes through where `CSS.supports` is missing (SSR, jsdom). */
export function safePresenceColor(color: string): string {
  if (typeof CSS === "undefined" || typeof CSS.supports !== "function") return color;
  return CSS.supports("color", color) ? color : FALLBACK_PRESENCE_COLOR;
}

/** One remote user's selection-range fill + border, grid-line placed like core's own RangeOverlay; color comes from the highlight itself via `--presence-color`, not a shadcn token. Memoized: the resolved rects keep identity across overlay renders (see `makePresencePlugin`'s memo), so an unchanged highlight never re-renders its divs on a local keystroke. */
const PresenceHighlightOverlay = memo(function PresenceHighlightOverlay({
  rect,
  color,
  windowStart,
  colOffset,
  pinStyle,
}: {
  rect: GridRect;
  color: string;
  windowStart: number;
  colOffset: number;
  pinStyle?: CSSProperties;
}) {
  const safeColor = safePresenceColor(color);
  return (
    <div
      data-grid-presence-overlay=""
      data-pinned={pinStyle ? "" : undefined}
      aria-hidden="true"
      className="pointer-events-none border border-[color-mix(in_oklch,var(--presence-color,var(--color-primary))_100%,transparent)] bg-[color-mix(in_oklch,var(--presence-color,var(--color-primary))_12%,transparent)]"
      style={{
        // positioned: cells are position:relative, so a static overlay would paint below them
        position: "relative",
        "--presence-color": safeColor,
        gridColumnStart: rect.x + colOffset,
        gridColumnEnd: rect.x + rect.width + colOffset,
        gridRowStart: rect.y - windowStart + 1,
        gridRowEnd: rect.y + rect.height - windowStart + 1,
        ...pinStyle,
        ...(pinStyle ? { zIndex: GRID_LAYER.pinnedOverlaySegment } : {}),
      } as CSSProperties}
    />
  );
});

/** The remote user's name chip, anchored at a highlight range's top-left VISIBLE corner — only rendered by the caller when that corner survives the window clamp. Memoized like the overlay node. */
const PresenceLabelChip = memo(function PresenceLabelChip({
  rect,
  color,
  label,
  windowStart,
  colOffset,
  pinStyle,
}: {
  rect: GridRect;
  color: string;
  label: string;
  windowStart: number;
  colOffset: number;
  pinStyle?: CSSProperties;
}) {
  const safeColor = safePresenceColor(color);
  return (
    <div
      data-grid-presence-label=""
      data-pinned={pinStyle ? "" : undefined}
      aria-hidden="true"
      className="pointer-events-none z-20 flex items-start justify-start"
      style={{
        "--presence-color": safeColor,
        gridColumnStart: rect.x + colOffset,
        gridColumnEnd: rect.x + colOffset + 1,
        gridRowStart: rect.y - windowStart + 1,
        gridRowEnd: rect.y - windowStart + 2,
        ...pinStyle,
      } as CSSProperties}
    >
      <span
        // Lightness below 0.62 gives white text, above gives black; white stays where relative color syntax is missing.
        className="-translate-y-1/2 rounded-sm bg-(--presence-color,var(--color-primary)) px-1.5 py-0.5 text-xs font-medium whitespace-nowrap text-(--presence-label-foreground,white) shadow-sm supports-[color:oklch(from_red_l_c_h)]:text-(--presence-label-foreground,oklch(from_var(--presence-color,var(--color-primary))_clamp(0,calc((0.62-l)*1000),1)_0_h_/_1))"
      >
        {label}
      </span>
    </div>
  );
});

/**
 * Resolves rowId-native entries to view-index {@link PresenceHighlight}s via the caller's
 * `rowId -> view row` map. A single-cell entry resolves to a 1×1 rect; a range entry paints one
 * rect per contiguous run of resolved rows × resolved columns.
 *
 * A rowId outside the current view is dropped silently (the rowId-native contract). An unresolved
 * column dev-warns once per instance. Column lookup is a linear scan over `visibleColumns`:
 * entry counts are small. A range entry paints at most `maxRects` fragments; the excess is
 * dropped and reported via `onExcessRects`.
 * Pure (no hooks), so tests can call it without React.
 */
export function resolveHighlights(
  entries: readonly PresenceHighlightEntry[],
  rowIdToViewRow: ReadonlyMap<string, number>,
  visibleColumns: readonly { id: string }[],
  onDroppedColumn?: (entry: RowIdPresenceHighlight) => void,
  onUnresolvedColumns?: (entry: RowIdRangePresenceHighlight, unresolvedCount: number) => void,
  onExcessRects?: (entry: RowIdRangePresenceHighlight, kept: number, total: number) => void,
  maxRects: number = MAX_RESOLVED_RECTS,
): PresenceHighlight[] {
  const resolved: PresenceHighlight[] = [];
  for (const entry of entries) {
    if (isRowIdPresenceHighlight(entry)) {
      const viewRow = rowIdToViewRow.get(entry.rowId);
      if (viewRow === undefined) continue;
      const col = visibleColumns.findIndex((c) => c.id === entry.columnId);
      if (col === -1) {
        onDroppedColumn?.(entry);
        continue;
      }
      resolved.push({
        id: entry.id,
        color: entry.color,
        range: { x: col, y: viewRow, width: 1, height: 1 },
        label: entry.label,
      });
      continue;
    }
    if (isRowIdRangePresenceHighlight(entry)) {
      const viewRows = entry.rowIds.map((rowId) => rowIdToViewRow.get(rowId)).filter((v): v is number => v !== undefined);
      const colIndexes = entry.columnIds.map((columnId) => visibleColumns.findIndex((c) => c.id === columnId));
      const viewCols = colIndexes.filter((col) => col !== -1);
      if (viewRows.length === 0 || viewCols.length === 0) continue;
      if (colIndexes.some((col) => col === -1)) {
        onUnresolvedColumns?.(entry, colIndexes.filter((col) => col === -1).length);
      }
      const rowRuns = contiguousRuns(viewRows);
      const colRuns = contiguousRuns(viewCols);
      const total = rowRuns.length * colRuns.length;
      let painted = 0;
      let capped = false;
      for (const rowRun of rowRuns) {
        for (const colRun of colRuns) {
          if (painted >= maxRects) {
            capped = true;
            break;
          }
          resolved.push({
            id: entry.id,
            color: entry.color,
            range: { x: colRun.min, y: rowRun.min, width: colRun.length, height: rowRun.length },
            label: entry.label,
          });
          painted += 1;
        }
        if (capped) break;
      }
      if (capped) onExcessRects?.(entry, maxRects, total);
      continue;
    }
    resolved.push(entry);
  }
  return resolved;
}

/** Ascending runs of contiguity in a number list: [0, 1, 3] -> [{ min: 0, length: 2 }, { min: 3, length: 1 }]; duplicates collapse. */
function contiguousRuns(values: number[]): { min: number; length: number }[] {
  const runs: { min: number; length: number }[] = [];
  let start = Number.POSITIVE_INFINITY;
  let prev = Number.NEGATIVE_INFINITY;
  for (const v of [...values].sort((a, b) => a - b)) {
    if (v === prev) continue;
    if (v !== prev + 1) {
      if (start !== Number.POSITIVE_INFINITY) runs.push({ min: start, length: prev - start + 1 });
      start = v;
    }
    prev = v;
  }
  if (start !== Number.POSITIVE_INFINITY) runs.push({ min: start, length: prev - start + 1 });
  return runs;
}

/**
 * Renders every active highlight into the overlay layer using the SAME window-clamp + pin-zone
 * segmentation pipeline core's own built-in overlays use (via `ctx`), so a highlight spanning a
 * pinned column splits into pinned/unpinned segments and paints at the pinned cell's actual screen
 * position exactly like a selection range does. This is the function registered as `OverlayPlugin`.
 * `highlights` must already be resolved to view-index (see {@link resolveHighlights}) — the caller
 * (`makePresencePlugin`) does that resolution itself since it's the one already subscribed to core
 * hooks inside `DataGridOverlays`'s render, keeping this function a plain (hook-free) renderer.
 */
export function renderPresenceOverlay(highlights: readonly PresenceHighlight[], ctx: OverlayPluginCtx): ReactNode {
  const { windowStart, clampRowStart, clampRowEnd, colCount, colOffset, pinTrack, splitRectByPinZones, clampRectToWindow } = ctx;
  const pinned = hasAnyPin(pinTrack) ? pinTrack : undefined;
  const segment = (rect: GridRect) => (pinned ? splitRectByPinZones(rect, pinned) : [{ rect, pinStyle: undefined }]);

  return (
    <>
      {/* entries are keyed by POSITION, not `id`: the id contract is "unique per entry", but a
          peer sending duplicate ids must not break reconciliation (unsupported duplicate React
          keys) — position is always unique per sibling */}
      {highlights.map((highlight, i) => {
        const clamped = clampRectToWindow(highlight.range, clampRowStart, clampRowEnd, colCount);
        if (!clamped) return null;
        // top-left corner chip only shows while that exact cell survives the clamp (same guard idea as core's own fill-handle corner check).
        const topLeftOnWindow = clamped.x === highlight.range.x && clamped.y === highlight.range.y;
        const topLeftPinStyle = pinned && pinned.pins[highlight.range.x]
          ? segment({ x: highlight.range.x, y: highlight.range.y, width: 1, height: 1 })[0]?.pinStyle
          : undefined;
        return (
          <Fragment key={i}>
            {segment(clamped).map((seg, j) => (
              <PresenceHighlightOverlay
                key={`presence-${i}-${j}`}
                rect={seg.rect}
                color={highlight.color}
                windowStart={windowStart}
                colOffset={colOffset}
                pinStyle={seg.pinStyle}
              />
            ))}
            {topLeftOnWindow && highlight.label && (
              <PresenceLabelChip
                rect={{ x: highlight.range.x, y: highlight.range.y, width: 1, height: 1 }}
                color={highlight.color}
                label={highlight.label}
                windowStart={windowStart}
                colOffset={colOffset}
                pinStyle={topLeftPinStyle}
              />
            )}
          </Fragment>
        );
      })}
    </>
  );
}
